fn same_order(xs: List[Int], r: List[Int], x: Int) -> Bool
  requires len(xs) >= 0
  ensures not result or not contains(r, x)
  ensures not result or len(r) <= len(xs)
  effects pure
  example same_order([1, 2, 1, 3], [2, 3], 1) == true
  example same_order([1, 2], [1, 2], 1) == false
  example same_order([4, 5], [4, 5], 9) == true
  example same_order([], [], 3) == true
{
  match xs {
    [] => match r {
      [] => true
      _ => false
    }
    [h, ..t] => if h == x then same_order(t, r, x) else match r {
      [] => false
      [rh, ..rt] => h == rh and same_order(t, rt, x)
    }
  }
}

